import{_ as o,o as r,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Comparison","description":"","frontmatter":{"title":"Comparison"},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md"}'),i={name:"comparison.md"};function n(s,e,l,p,c,d){return r(),a("div",null,[...e[0]||(e[0]=[t('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h1><p>An honest look at the alternatives. Wingport isn&#39;t the right choice for everyone — here&#39;s how to decide.</p><h2 id="vs-hand-rolling-an-edge-function" tabindex="-1">vs. hand-rolling an edge function <a class="header-anchor" href="#vs-hand-rolling-an-edge-function" aria-label="Permalink to &quot;vs. hand-rolling an edge function&quot;">​</a></h2><p>The &quot;correct&quot; DIY path today: store your key in Supabase secrets, write a Deno edge function that verifies the JWT, forwards to the provider, and streams back.</p><p><strong>What you write yourself:</strong> JWT verification, per-user rate limiting (needs tables), usage metering, SSE proxying within edge runtime CPU/wall-clock limits, provider error handling, retries, fallback, and the entire mobile client half: stream parsing, reconnection, cancellation, typed errors.</p><p><strong>What Wingport is:</strong> that exact function — hardened, tested, maintained, and paired with a client SDK that handles the mobile half. You keep full ownership (it runs in your project); you stop maintaining boilerplate.</p><p>Choose DIY if your needs are truly one-off and you enjoy owning the code. Choose Wingport if you&#39;d rather own a config file.</p><h2 id="vs-firebase-ai-logic" tabindex="-1">vs. Firebase AI Logic <a class="header-anchor" href="#vs-firebase-ai-logic" aria-label="Permalink to &quot;vs. Firebase AI Logic&quot;">​</a></h2><p>Firebase AI Logic solves the same key-security problem — proof the problem is real. But it&#39;s Gemini-only, Google-only, Firebase-only.</p><p>Wingport is neutral on every axis: any provider (Anthropic, OpenAI, Google), any backend (Supabase first, Firebase planned), and open source, so you&#39;re never locked into one vendor&#39;s model roadmap.</p><h2 id="vs-openrouter-litellm" tabindex="-1">vs. OpenRouter / LiteLLM <a class="header-anchor" href="#vs-openrouter-litellm" aria-label="Permalink to &quot;vs. OpenRouter / LiteLLM&quot;">​</a></h2><p>OpenRouter and LiteLLM are excellent <strong>server-side</strong> routers: one API across many providers. But they have no concept of your <em>end users</em> — no per-user auth, no per-user quotas, no mobile SDK — and OpenRouter is a hosted middleman in your request path.</p><p>Wingport is mobile-first: it authenticates individual end users against your existing auth, enforces per-user limits, meters per-user usage, and ships a client SDK built for unreliable networks. You can even use OpenRouter <em>as a provider inside</em> Wingport if you want its routing. <span class="VPBadge warning">Planned</span></p><h2 id="vs-calling-providers-directly-from-the-app" tabindex="-1">vs. calling providers directly from the app <a class="header-anchor" href="#vs-calling-providers-directly-from-the-app" aria-label="Permalink to &quot;vs. calling providers directly from the app&quot;">​</a></h2><p>Shipping <code>sk-...</code> in your binary. Please don&#39;t. Any user can extract the key via a debugging proxy, and provider terms prohibit client-side keys for exactly this reason. There is no RLS trick or obfuscation that fixes this: <strong>any secret that reaches the client is public.</strong></p><hr>',17)])])}const g=o(i,[["render",n]]);export{u as __pageData,g as default};
